// TypeScript Version: 4.1

/**
* Interface describing `dindexOfGreaterThanSorted`.
*/
interface Routine {
	/**
	* Returns the index of the first element in a sorted double-precision floating-point strided array which is greater than a specified search element.
	*
	* ## Notes
	*
	* -   The input strided array must be sorted in ascending order.
	* -   If the function is unable to find an element which is greater than a search element, the function returns `-1`.
	*
	* @param N - number of indexed elements
	* @param searchElement - search element
	* @param x - sorted input array
	* @param strideX - stride length
	* @returns index
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
	*
	* var idx = dindexOfGreaterThanSorted( x.length, 2.0, x, 1 );
	* // returns 3
	*/
	( N: number, searchElement: number, x: Float64Array, strideX: number ): number;

	/**
	* Returns the index of the first element in a sorted double-precision floating-point strided array which is greater than a specified search element using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   The input strided array must be sorted in ascending order.
	* -   If the function is unable to find an element which is greater than a search element, the function returns `-1`.
	*
	* @param N - number of indexed elements
	* @param searchElement - search element
	* @param x - sorted input array
	* @param strideX - stride length
	* @param offsetX - starting index
	* @returns index
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
	*
	* var idx = dindexOfGreaterThanSorted.ndarray( x.length, 2.0, x, 1, 0 );
	* // returns 3
	*/
	ndarray( N: number, searchElement: number, x: Float64Array, strideX: number, offsetX: number ): number;
}

/**
* Returns the index of the first element in a sorted double-precision floating-point strided array which is greater than a specified search element.
*
* ## Notes
*
* -   The input strided array must be sorted in ascending order.
* -   If the function is unable to find an element which is greater than a search element, the function returns `-1`.
*
* @param N - number of indexed elements
* @param searchElement - search element
* @param x - sorted input array
* @param strideX - stride length
* @returns index
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = dindexOfGreaterThanSorted( x.length, 2.0, x, 1 );
* // returns 3
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = dindexOfGreaterThanSorted.ndarray( x.length, 2.0, x, 1, 0 );
* // returns 3
*/
declare var dindexOfGreaterThanSorted: Routine;


// EXPORTS //

export = dindexOfGreaterThanSorted;
